cat > /tmp/opencode/check.mjs <<'EOF'
const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  if (msg.method === 'Runtime.exceptionThrown') console.log('EXCEPTION', msg.params.exceptionDetails.text);
  if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') console.log('LOG_ERROR', msg.params.entry.text);
};
const send = (method, params={}) => new Promise(resolve => { const n=++id; pending.set(n,resolve); ws.send(JSON.stringify({id:n,method,params})); });
const evalJS = async expression => (await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true})).result.result.value;
await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
await send('Page.navigate',{url:'http://127.0.0.1:5173'});
await new Promise(r=>setTimeout(r,2000));
console.log('initial', await evalJS(`JSON.stringify({title:document.title, webgl:!!document.querySelector('#scene canvas'), launch:document.querySelector('#launchOverlay').className})`));
await evalJS(`document.querySelector('#launchOverlay').click()`);
await new Promise(r=>setTimeout(r,250));
await evalJS(`document.querySelector('#launchOverlay').click()`);
console.log('launched', await evalJS(`JSON.stringify({launch:document.querySelector('#launchOverlay').className, phase:document.querySelector('#phaseChip span').textContent, time:document.querySelector('#phaseTime').textContent})`));
await new Promise(r=>setTimeout(r,10500));
console.log('manual', await evalJS(`JSON.stringify({phase:document.querySelector('#phaseChip span').textContent, dashDisabled:document.querySelector('#dashBtn').disabled, timer:document.querySelector('#phaseTime').textContent})`));
await evalJS(`document.querySelector('#dashBtn').click()`);
console.log('dash feed', await evalJS(`document.querySelector('#feedText').textContent`));
await evalJS(`document.querySelector('[data-camera="side"]').click(); document.querySelector('[data-camera="pov"]').click(); document.querySelector('[data-view="workshop"]').click()`);
await new Promise(r=>setTimeout(r,500));
console.log('workshop', await evalJS(`JSON.stringify({active:document.querySelector('#workshopView').classList.contains('active'), canvas:!!document.querySelector('#workshopPreview canvas'), options:document.querySelectorAll('.part-option').length, title:document.querySelector('#previewTitle').textContent})`));
await evalJS(`document.querySelector('[data-part="blade"]').click(); document.querySelectorAll('.part-option')[2].click()`);
console.log('customized', await evalJS(`JSON.stringify({options:document.querySelectorAll('.part-option').length, selected:document.querySelector('.part-option.selected b').textContent})`));
ws.close();
EOF
