const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find((entry) => entry.type === 'page' && entry.url.startsWith('http://127.0.0.1:5173'));
if (!target) throw new Error('Vite page not found in Chromium');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = ({ data }) => {
  const message = JSON.parse(data);
  if (message.id && pending.has(message.id)) { pending.get(message.id)(message); pending.delete(message.id); }
};
const send = (method, params = {}) => new Promise((resolve) => {
  const requestId = ++id;
  pending.set(requestId, resolve);
  ws.send(JSON.stringify({ id: requestId, method, params }));
});
const evaluate = async (expression) => {
  const response = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (response.result.exceptionDetails) throw new Error(response.result.exceptionDetails.text);
  return response.result.result.value;
};
await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:5173' });
await evaluate(`new Promise(resolve => setTimeout(resolve, 1200))`);
await evaluate(`(() => {
  document.querySelector('#modeSelect').value = 'practice';
  document.querySelector('#difficultySelect').value = 'BEGINNER';
  document.querySelector('#personalitySelect').value = 'DEFENSIVE';
  document.querySelector('#startMatchBtn').click();
  const { state, player, opponent } = window.__soulsspinTest;
  state.running = true; state.launched = true; state.phase = 'manual'; state.phaseLeft = 1000;
  player.x = -1; player.z = 0; player.vx = 0; player.vz = 0; player.spin = 100; player.health = 100;
  player.dashUsed = false; player.tiltUsed = false; player.abilityUsed = false;
  opponent.x = 5; opponent.z = 0; opponent.vx = 0; opponent.vz = 0;
})()`);
await evaluate(`new Promise(resolve => requestAnimationFrame(() => resolve(true)))`);
const dash = await evaluate(`(() => {
  const { player } = window.__soulsspinTest;
  document.querySelector('#dashBtn').click();
  return JSON.stringify({ used: player.dashUsed, tiltUsed: player.tiltUsed, dashDisabled: document.querySelector('#dashBtn').disabled, tiltDisabled: document.querySelector('#tiltBtn').disabled, spin: player.spin });
})()`);
await evaluate(`(() => {
  const { player } = window.__soulsspinTest;
  player.dashUsed = false; player.tiltUsed = false; player.spin = 100;
  window.__soulsspinTest.state.moveX = 0; window.__soulsspinTest.state.moveZ = -1;
})()`);
await evaluate(`new Promise(resolve => requestAnimationFrame(() => resolve(true)))`);
const tilt = await evaluate(`(() => {
  const { player } = window.__soulsspinTest;
  document.querySelector('#tiltBtn').click();
  return JSON.stringify({ used: player.tiltUsed, dashUsed: player.dashUsed, dashDisabled: document.querySelector('#dashBtn').disabled, tiltDisabled: document.querySelector('#tiltBtn').disabled, spin: player.spin, tiltX: player.tiltX });
})()`);
await evaluate(`(() => {
  const { player } = window.__soulsspinTest;
  player.health = 50; player.spin = 80; player.abilityUsed = false; player.dashUsed = false; player.tiltUsed = false;
  window.__soulsspinTest.state.moveX = 0; window.__soulsspinTest.state.moveZ = 0;
})()`);
await evaluate(`new Promise(resolve => requestAnimationFrame(() => resolve(true)))`);
const avatar = await evaluate(`(() => {
  const { player } = window.__soulsspinTest;
  const enabledBefore = !document.querySelector('#avatarBtn').disabled;
  document.querySelector('#avatarBtn').click();
  return JSON.stringify({ enabledBefore, used: player.abilityUsed, timer: player.abilityTimer, spin: player.spin, disabledAfter: document.querySelector('#avatarBtn').disabled });
})()`);
console.log(JSON.stringify({ dash: JSON.parse(dash), tilt: JSON.parse(tilt), avatar: JSON.parse(avatar) }, null, 2));
